module float_multi (
	input clk, rst, 
	input [31:0] a, b,
	output reg [31:0] z
	);

	reg [2:0] counter;
	reg [23:0] a_mantissa, b_mantissa, z_mantissa;
	reg [9:0] a_exponent, b_exponent, z_exponent;
	reg a_sign, b_sign, z_sign;
	wire [49:0] product;
	reg guard_bit, round_bit, sticky;
	// TODO: Fill in the implementation here
	assign product = {1'b1,a_mantissa} * {1'b1,b_mantissa};
	//reg [31:0] temp;
	always @(posedge clk) begin
		if(rst) begin
			counter <= 0;
		end
		else begin
			case(counter)
				0:begin
					a_mantissa <= a[22:0];
					b_mantissa <= b[22:0];
					a_exponent <= a[30:23] - 8'd127;
					b_exponent <= b[30:23] - 8'd127;
					a_sign <= a[31];
					b_sign <= b[31];
					z_exponent <= a_exponent + b_exponent + 8'd127;
					z_sign <= a_sign ^ b_sign;
					counter <= counter + 1;
				end
				1:begin
					if((~|a_exponent) && (~|b_exponent)) begin //check if either is zero
						counter <= 3;
					end
					else if ((a_exponent > 9'd381) || (b_exponent > 9'd381)) begin //check if inf
						counter <= 3;
					end
					else if (((&a_exponent) && (|a_mantissa)) || ((&b_exponent) && (|b_mantissa))) begin //check if nan
						counter <= 3;
					end
					else begin
						if(a_exponent >= 0) begin //check for denorm
							a_mantissa <= a_mantissa << 1;
							a_exponent <= a_exponent - 1;
						end
						if(b_exponent >= 0) begin //check for denorm
							b_mantissa <= b_mantissa << 1;
							b_exponent <= b_exponent - 1;
						end
						counter <= counter + 1;
					end
				end
				2:begin
					guard_bit <= product[23];
					round_bit <= product[22];
					sticky <= (product[21:0] != 0);
					counter <= counter + 1;
				end
				3:begin
					if(z_exponent > 9'd254) begin //overflow
						z_exponent <= 9'd255;
						z_mantissa <= 23'd0;
						z_sign <= 1'b0;
					end
					else if(z_exponent < 0) begin //underflow
						z_exponent <= 9'd0;
						z_mantissa <= 23'd0;
						z_sign <= 1'b0;
					end
					else begin //normalization
						if(product[49]) begin
							z_mantissa <= product[49:26];
							z_exponent <= z_exponent + 1;
						end
						else begin
							z_mantissa <= product[48:25];
							if(~(|z_mantissa)) begin
								z_exponent <= 9'd0;
							end
						end
					end
					counter <= counter + 1;
				end
				4:begin
					z <= {z_sign,z_exponent[7:0],z_mantissa[22:0]};
					counter <= 0;
				end
			endcase
		end
	end

endmodule
